export function getControlSchemeText() {
  return [
    'PITCH: ↑/W (up)  ↓/S (down)',
    'ROLL:  ←/A (left)  →/D (right)',
    'THROTTLE: Shift (↑)  Ctrl (↓)',
    'CAMERA: C  |  PAUSE: Esc/P  |  MUTE: M',
    'GEAR: G  |  FLAPS: F/V  |  SCREENSHOT: F12',
    'MOUSE: Drag = Stick  |  TOUCH: Drag = Stick',
  ];
}
